from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        # Build trie
        children = [{}]
        count = [0]
        depth = [0]

        word_nodes = []
        for w in words:
            cur = 0
            count[0] += 1
            nodes = [0]
            for c in w:
                ch = children[cur]
                if c not in ch:
                    children.append({})
                    count.append(0)
                    depth.append(depth[cur] + 1)
                    ch[c] = len(children) - 1
                cur = ch[c]
                count[cur] += 1
                nodes.append(cur)
            word_nodes.append(nodes)

        max_d = max(depth) if depth else 0
        cnt_qualified = [0] * (max_d + 2)
        unique_node = [-1] * (max_d + 2)

        for v in range(1, len(children)):
            if count[v] >= k:
                d = depth[v]
                cnt_qualified[d] += 1
                if cnt_qualified[d] == 1:
                    unique_node[d] = v

        D = 0
        for d in range(max_d, 0, -1):
            if cnt_qualified[d] >= 1:
                D = d
                break

        G = 0
        for d in range(max_d, 0, -1):
            if cnt_qualified[d] >= 2:
                G = d
                break

        u_D = unique_node[D] if (D > G and D > 0) else -1

        ans = []
        kp1 = k + 1
        for i in range(n):
            nodes = word_nodes[i]
            wlen = len(words[i])

            # B_max: deepest depth on word i's path with count >= k+1
            B = 0
            for d in range(wlen, 0, -1):
                if count[nodes[d]] >= kp1:
                    B = d
                    break

            # A_max
            if D <= G:
                A = G
            else:
                if wlen >= D and nodes[D] == u_D:
                    A = G
                else:
                    A = D

            ans.append(A if A > B else B)

        return ans
